package fraymus.workspace;

import org.json.*;
import java.nio.file.Path;
import java.time.Instant;
import java.util.*;

/** Prospective native decision experiment; never writes an active controller. */
final class DecisionStudy065 {
    static final String PROTOCOL="target-window-decision-065-v1";
    static final int TOTAL=216;
    private static final class Identity {static final String VALUE=implementation();}
    static String source(){return Identity.VALUE;}
    private static String implementation(){var b=new StringBuilder(PROTOCOL).append(Stopping063.source()).append(Calibration065.SHA);var q=new ArrayDeque<Class<?>>();q.addAll(List.of(DecisionStudy065.class,DecisionPolicy065.class,Calibration065.class));while(!q.isEmpty()){var c=q.remove();try(var in=c.getResourceAsStream(c.getName().substring(c.getPackageName().length()+1)+".class")){b.append(MapDefinition.sha(in.readAllBytes()));}catch(Exception e){throw new IllegalStateException(e);}Arrays.stream(c.getDeclaredClasses()).sorted(Comparator.comparing(Class::getName)).forEach(q::add);}return MeasurementStore.hash(b.toString());}
    static JSONArray cases(boolean shifted){var r=new Random(shifted?65002:65001);var out=new JSONArray();for(int group=0;group<2;group++)for(int i=0;i<(shifted?6:30);i++){double angle=12+20*r.nextDouble(),ratio=group==0?.85+.14*r.nextDouble():1.01+.19*r.nextDouble(),center=.02+.34*r.nextDouble();if(shifted)switch(i%3){case 0->angle=10;case 1->angle=34;case 2->ratio=1;}
        out.put(new JSONObject().put("angleDeg",angle).put("frictionRatio",ratio).put("centerM",center).put("halfWidthM",new double[]{.012,.024,.045}[i%3]));}return out;}
    static JSONObject manifest(){return new JSONObject().put("protocol",PROTOCOL).put("source",source()).put("model",Calibration065.info()).put("tasks",cases(false)).put("shifted",cases(true)).put("methods",new JSONArray(DecisionPolicy065.METHODS)).put("speeds",new JSONArray(DecisionPolicy065.SPEEDS)).put("successReward",1).put("missCost",2).put("refusalCost",.15).put("executionCost",.02).put("minimumGainSimple",.10).put("minimumGainFixed",.05).put("minimumSuccessFraction",.5).put("totalDecisionSlots",TOTAL).put("controllerAuthority",false);}
    static JSONObject evaluation(JSONArray rows){
        var result=DecisionPolicy065.evaluate(rows);var subgroups=new JSONObject();for(String key:List.of("accelerating","slowing","width12mm","width24mm","width45mm")){var subset=new JSONArray();for(Object raw:rows){var t=((JSONObject)raw).getJSONObject("task");boolean match=switch(key){case "accelerating"->t.getDouble("frictionRatio")<1;case "slowing"->t.getDouble("frictionRatio")>1;default->Math.abs(t.getDouble("halfWidthM")-(key.equals("width12mm")?.012:key.equals("width24mm")?.024:.045))<1e-12;};if(match)subset.put(raw);}subgroups.put(key,DecisionPolicy065.evaluate(subset));}
        boolean qualified=qualifies(result);
        return result.put("subgroups",subgroups).put("qualified",qualified).put("proposed","pooled").put("controllerAuthority",false).put("interpretation","Declared empirical decision-value gate; no statistical or physical guarantee and no automatic promotion");
    }
    static boolean qualifies(JSONObject result){var m=result.getJSONObject("methods");var p=m.getJSONObject("pooled");return result.getJSONObject("pairedPooledMinus").getJSONObject("simple").getDouble("meanDelta")>=.10&&result.getJSONObject("pairedPooledMinus").getJSONObject("fixed").getDouble("meanDelta")>=.05&&p.getDouble("allTaskMissRate")<=m.getJSONObject("simple").getDouble("allTaskMissRate")&&p.getDouble("allTaskSuccessRate")>=.5;}
    static void run(JSONObject job,Path dir,Runnable cancel,FraynixOutcome061.Progress progress)throws Exception{
        job.put("manifest065",manifest()).put("tasks065",new JSONArray()).put("shifted065",new JSONArray()).put("progress",0).put("nativeExecutions",0).put("total",TOTAL);progress.save("Decision comparison declared");
        for(boolean shifted:new boolean[]{false,true})for(Object raw:cases(shifted)){cancel.run();var task=(JSONObject)raw;var row=new JSONObject().put("task",task).put("plannedAt",Instant.now().toString()).put("plan",DecisionPolicy065.plan(task)).put("results",new JSONObject());job.getJSONArray(shifted?"shifted065":"tasks065").put(row);progress.save("All three plans saved before observation");
            for(String method:DecisionPolicy065.METHODS){cancel.run();var decision=row.getJSONObject("plan").getJSONObject("decisions").getJSONObject(method);JSONObject record=null;if(decision.getBoolean("execute")){record=Stopping063.trial(DecisionPolicy065.definition(task,decision.getDouble("speedMps")),"baseline",180,4,dir,cancel);job.put("nativeExecutions",job.getInt("nativeExecutions")+1);}
                var outcome=new JSONObject().put("outcome",DecisionPolicy065.outcome(task,decision,record));if(record!=null)outcome.put("record",record);row.getJSONObject("results").put(method,outcome);job.put("progress",job.getInt("progress")+1);progress.save(shifted?"Domain refusal retained":method+" decision outcome retained");}
        }
        job.put("evaluation065",evaluation(job.getJSONArray("tasks065"))).put("shiftedEvaluation065",DecisionPolicy065.evaluate(job.getJSONArray("shifted065")));job.put("accepted",job.getJSONObject("evaluation065").getBoolean("qualified")).put("reason",job.getBoolean("accepted")?"Pooled passed declared decision-value gate; no promotion":"Pooled did not pass declared decision-value gate; original outcomes retained");audit(job);progress.save("Decision comparison verified");
    }
    static void audit(JSONObject job){
        if(!manifest().similar(job.getJSONObject("manifest065")))throw new IllegalStateException("Decision manifest differs");var ids=new HashSet<String>();int executions=0;
        for(boolean shifted:new boolean[]{false,true}){var rows=job.getJSONArray(shifted?"shifted065":"tasks065");var expected=cases(shifted);if(rows.length()!=expected.length())throw new IllegalStateException("Incomplete task partition");for(int i=0;i<rows.length();i++){var row=rows.getJSONObject(i);var task=expected.getJSONObject(i);if(!task.similar(row.getJSONObject("task"))||!DecisionPolicy065.plan(task).similar(row.getJSONObject("plan")))throw new IllegalStateException("Task or prior plan differs");Instant before=Instant.parse(row.getString("plannedAt"));var results=row.getJSONObject("results");if(!results.keySet().equals(new HashSet<>(DecisionPolicy065.METHODS)))throw new IllegalStateException("Missing or extra decision result");
            for(String method:DecisionPolicy065.METHODS){var result=results.getJSONObject(method);var d=row.getJSONObject("plan").getJSONObject("decisions").getJSONObject(method);JSONObject record=result.optJSONObject("record");if(d.getBoolean("execute")){if(shifted||record==null)throw new IllegalStateException("Unsupported or missing execution");Stopping063.verify(record);if(!ids.add(record.getString("id"))||record.getInt("ticks")!=180||record.getInt("stride")!=4||!record.getString("variant").equals("baseline")||!record.getJSONObject("definition").similar(DecisionPolicy065.definition(task,d.getDouble("speedMps")))||Instant.parse(record.getString("observedAt")).isBefore(before))throw new IllegalStateException("Execution identity, definition or chronology differs");executions++;}else if(result.has("record"))throw new IllegalStateException("Refusal has a fabricated record");if(!DecisionPolicy065.outcome(task,d,record).similar(result.getJSONObject("outcome")))throw new IllegalStateException("Decision outcome differs");}
        }}
        if(job.getInt("progress")!=TOTAL||job.getInt("total")!=TOTAL||job.getInt("nativeExecutions")!=executions||!evaluation(job.getJSONArray("tasks065")).similar(job.getJSONObject("evaluation065"))||job.getBoolean("accepted")!=job.getJSONObject("evaluation065").getBoolean("qualified")||!DecisionPolicy065.evaluate(job.getJSONArray("shifted065")).similar(job.getJSONObject("shiftedEvaluation065")))throw new IllegalStateException("Decision counts or evaluation differ");
    }
    static JSONObject summary(JSONObject job){var out=new JSONObject().put("jobId",job.getString("id")).put("status",job.getString("status")).put("nativeExecutions",job.optInt("nativeExecutions")).put("model",Calibration065.info());if(job.has("evaluation065"))out.put("evaluation",job.getJSONObject("evaluation065")).put("shiftedEvaluation",job.getJSONObject("shiftedEvaluation065"));return out;}
}
